sql.where:
v.v_parent_idx = 0
AND v.v_rating = #{reviewVO.ratingFilter}
AND v.v_active = #{reviewVO.blindFilter}
AND EXISTS (SELECT 1 FROM review r2 WHERE r2.v_parent_idx = v.v_idx)
AND NOT EXISTS (SELECT 1 FROM review r2 WHERE r2.v_parent_idx = v.v_idx)
AND (u.u_name LIKE CONCAT('%', #{reviewVO.searchWord}, '%') OR s.s_name LIKE CONCAT('%', #{reviewVO.searchWord}, '%'))

mapper.select:
SELECT COUNT(*)
  FROM review_report rr


        rr.rr_status = #{statusFilter}

SELECT rr.rr_idx AS rvr_idx, rr.v_idx AS rev_idx, rr.u_idx AS user_idx, u.u_name AS user_name, rr.rr_reason AS rvr_reason, rr.rr_status AS rvr_status, rr.rr_admin_reply AS rvr_admin_reply, rr.rr_created AS rvr_created, v.v_content AS rev_content, v.v_rating AS rev_rating, v.v_active AS rev_active, s.s_name AS spc_name, writer.u_name AS writer_name FROM review_report rr LEFT JOIN user u ON rr.u_idx = u.u_idx LEFT JOIN review v ON rr.v_idx = v.v_idx LEFT JOIN space s ON v.s_idx = s.s_idx LEFT JOIN user writer ON v.u_idx = writer.u_idx
rr.rr_status = #{statusFilter}
ORDER BY rr.rr_created DESC LIMIT #{numPerPage} OFFSET #{offset}

mapper.update:
UPDATE review_report
   SET rr_status      = #{rvrStatus},
       rr_admin_reply = #{rvrAdminReply}
 WHERE rr_idx = #{rvrIdx}
